"use strict";(self.webpackChunkenterprise_ai_agents_applied_ml_book=self.webpackChunkenterprise_ai_agents_applied_ml_book||[]).push([[1083],{8627(e,t,n){n.r(t),n.d(t,{assets:()=>l,contentTitle:()=>c,default:()=>u,frontMatter:()=>i,metadata:()=>a,toc:()=>p});const a=JSON.parse('{"id":"part2-backend-platform-security/fastapi-request-mapping","title":"From an HTTP Message to FastAPI Function Arguments","description":"The HTTP chapter separated method, URL, headers, and body. This chapter follows one request through FastAPI and shows exactly how each part becomes a typed Python value. The Pydantic chapter then explains the body mod...","source":"@site/docs/part2-backend-platform-security/03-fastapi-request-mapping.mdx","sourceDirName":"part2-backend-platform-security","slug":"/part2-backend-platform-security/03-fastapi-request-mapping","permalink":"/tutorials/part2-backend-platform-security/03-fastapi-request-mapping","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1785375762000,"sidebarPosition":3,"frontMatter":{"title":"From an HTTP Message to FastAPI Function Arguments","slug":"/part2-backend-platform-security/03-fastapi-request-mapping","description":"The HTTP chapter separated method, URL, headers, and body. This chapter follows one request through FastAPI and shows exactly how each part becomes a typed Python value. The Pydantic chapter then explains the body mod...","sidebar_label":"3. FastAPI request mapping","pagination_label":"3. FastAPI request mapping","hide_title":true,"hide_table_of_contents":true},"sidebar":"bookSidebar","previous":{"title":"2. HTTP methods","permalink":"/tutorials/part2-backend-platform-security/02-http-methods"},"next":{"title":"4. Pydantic data models","permalink":"/tutorials/part2-backend-platform-security/04-pydantic-data-models"}}');var o=n(4848),s=n(8453),r=n(8172);const d=JSON.parse('{"sourcePath":"part2-backend-platform-security/03-fastapi-request-mapping.html","route":"/part2-backend-platform-security/03-fastapi-request-mapping","kind":"chapter","partId":"part2","partLabel":"Part II - Backend, Platform & Security","accent":"teal","heading":"From an HTTP Message to FastAPI Function Arguments","title":"From an HTTP Message to FastAPI Function Arguments","description":"The HTTP chapter separated method, URL, headers, and body. This chapter follows one request through FastAPI and shows exactly how each part becomes a typed Python value. The Pydantic chapter then explains the body mod...","readingMinutes":4,"bodyClass":"","normalizeMath":false,"toc":[{"id":"1-the-endpoint-declares-the-contract","label":"1) The endpoint declares the contract"},{"id":"2-a-real-http-request-message-what-the-client-sends","label":"2) A real HTTP request message (what the client sends)"},{"id":"3-how-fastapi-maps-that-message-into-your-function-arguments","label":"3) How FastAPI maps that message into your function arguments"},{"id":"4-what-fastapi-effectively-calls-conceptually","label":"4) What FastAPI effectively calls (conceptually)"},{"id":"5-how-fastapi-decides-where-a-parameter-comes-from","label":"5) How FastAPI decides where a parameter comes from"},{"id":"6-invalid-input-stops-before-business-logic","label":"6) Invalid input stops before business logic"},{"id":"7-the-return-value-travels-back-through-a-response-contract","label":"7) The return value travels back through a response contract"}],"html":"<div class=\\"container\\">\\n        \\n        <p class=\\"lead\\">The HTTP chapter separated method, URL, headers, and\\n        body. This chapter follows one request through FastAPI and shows exactly\\n        how each part becomes a typed Python value. The Pydantic chapter then\\n        explains the body model in depth.</p>\\n\\n        <h2 id=\\"1-the-endpoint-declares-the-contract\\">1) The endpoint declares the contract</h2>\\n<pre><code class=\\"language-python\\">from typing import Annotated\\n\\nfrom fastapi import FastAPI, Header, Query\\nfrom pydantic import BaseModel, Field\\n\\napp = FastAPI()\\n\\nclass QueryReq(BaseModel):\\n    question: str = Field(min_length=1, max_length=2_000)\\n\\nclass QueryResponse(BaseModel):\\n    collection_id: str\\n    q: str\\n    top_k: int\\n    auth_header: str | None\\n\\n@app.post(\\n    \\"/collections/{collection_id}/query\\",\\n    response_model=QueryResponse,\\n)\\ndef query(\\n    collection_id: str,\\n    req: QueryReq,\\n    top_k: Annotated[int, Query(ge=1, le=50)] = 5,\\n    authorization: Annotated[str | None, Header()] = None,\\n) -&gt; QueryResponse:\\n    return QueryResponse(\\n        collection_id=collection_id,\\n        q=req.question,\\n        top_k=top_k,\\n        auth_header=authorization,\\n    )</code></pre>\\n\\n        <p>The route decorator and function signature together form the\\n        boundary contract. FastAPI inspects the signature once when the\\n        application starts and builds validation plus OpenAPI metadata from it.</p>\\n\\n        <hr>\\n\\n        <h2 id=\\"2-a-real-http-request-message-what-the-client-sends\\">2) A real HTTP request message (what the client sends)</h2>\\n<pre><code class=\\"language-http\\">POST /collections/policies/query?top_k=10 HTTP/1.1\\nHost: api.example.com\\nAuthorization: Bearer abc.def.ghi\\nContent-Type: application/json\\nAccept: application/json\\n\\n{\\"question\\": \\"What does my policy say about refunds?\\"}</code></pre>\\n\\n        <p>There are five separate inputs here: method, path template, path\\n        parameter, query parameter, header, and JSON body. FastAPI does not\\n        merge them into one undifferentiated dictionary.</p>\\n\\n        <div class=\\"figure-card\\">\\n          <h3 id=\\"visual-one-request-several-typed-sources\\">Visual: one request, several typed sources</h3>\\n          <svg class=\\"viz\\" viewBox=\\"0 0 980 300\\" role=\\"img\\" aria-label=\\"HTTP request parts mapped to FastAPI arguments\\">\\n            <defs>\\n              <marker id=\\"mapping-arrow\\" viewBox=\\"0 0 10 10\\" refX=\\"9\\" refY=\\"5\\" markerWidth=\\"8\\" markerHeight=\\"8\\" orient=\\"auto\\">\\n                <path d=\\"M0 0 L10 5 L0 10 z\\" class=\\"accentFill\\"></path>\\n              </marker>\\n            </defs>\\n            <rect x=\\"28\\" y=\\"42\\" width=\\"310\\" height=\\"216\\" rx=\\"14\\" class=\\"box2\\"></rect>\\n            <text x=\\"183\\" y=\\"78\\" text-anchor=\\"middle\\" class=\\"title\\">HTTP message</text>\\n            <text x=\\"64\\" y=\\"116\\" class=\\"label\\">route</text>\\n            <text x=\\"166\\" y=\\"116\\" class=\\"muted\\">POST /collections/policies/query</text>\\n            <text x=\\"64\\" y=\\"150\\" class=\\"label\\">query</text>\\n            <text x=\\"166\\" y=\\"150\\" class=\\"muted\\">top_k=10</text>\\n            <text x=\\"64\\" y=\\"184\\" class=\\"label\\">header</text>\\n            <text x=\\"166\\" y=\\"184\\" class=\\"muted\\">Authorization: Bearer ...</text>\\n            <text x=\\"64\\" y=\\"218\\" class=\\"label\\">body</text>\\n            <text x=\\"166\\" y=\\"218\\" class=\\"muted\\">{\\"question\\": \\"...\\"}</text>\\n\\n            <rect x=\\"426\\" y=\\"42\\" width=\\"190\\" height=\\"216\\" rx=\\"14\\" class=\\"box\\"></rect>\\n            <text x=\\"521\\" y=\\"78\\" text-anchor=\\"middle\\" class=\\"title\\">FastAPI</text>\\n            <text x=\\"521\\" y=\\"118\\" text-anchor=\\"middle\\" class=\\"muted\\">route match</text>\\n            <text x=\\"521\\" y=\\"150\\" text-anchor=\\"middle\\" class=\\"muted\\">extract</text>\\n            <text x=\\"521\\" y=\\"182\\" text-anchor=\\"middle\\" class=\\"muted\\">convert</text>\\n            <text x=\\"521\\" y=\\"214\\" text-anchor=\\"middle\\" class=\\"muted\\">validate</text>\\n\\n            <rect x=\\"704\\" y=\\"42\\" width=\\"248\\" height=\\"216\\" rx=\\"14\\" class=\\"box2\\"></rect>\\n            <text x=\\"828\\" y=\\"78\\" text-anchor=\\"middle\\" class=\\"title\\">Python arguments</text>\\n            <text x=\\"732\\" y=\\"116\\" class=\\"muted\\">collection_id = \\"policies\\"</text>\\n            <text x=\\"732\\" y=\\"150\\" class=\\"muted\\">top_k = 10</text>\\n            <text x=\\"732\\" y=\\"184\\" class=\\"muted\\">authorization = \\"Bearer ...\\"</text>\\n            <text x=\\"732\\" y=\\"218\\" class=\\"muted\\">req = QueryReq(...)</text>\\n\\n            <line x1=\\"338\\" y1=\\"150\\" x2=\\"426\\" y2=\\"150\\" class=\\"accent\\" stroke-width=\\"2\\" marker-end=\\"url(#mapping-arrow)\\"></line>\\n            <line x1=\\"616\\" y1=\\"150\\" x2=\\"704\\" y2=\\"150\\" class=\\"accent\\" stroke-width=\\"2\\" marker-end=\\"url(#mapping-arrow)\\"></line>\\n          </svg>\\n        </div>\\n\\n        <hr>\\n\\n        <h2 id=\\"3-how-fastapi-maps-that-message-into-your-function-arguments\\">3) How FastAPI maps that message into your function arguments</h2>\\n\\n        <div class=\\"step-card\\">\\n            <h3 id=\\"a-method-path-decide-which-function-runs\\">A) Method + path decide which function runs</h3>\\n            <ul>\\n                <li><strong>Method</strong> = POST</li>\\n                <li><strong>Path</strong> = <code>/query</code></li>\\n            </ul>\\n            <p>So FastAPI matches\\n            <code>@app.post(\\"/collections/{collection_id}/query\\")</code> and\\n            selects <code>query(...)</code>. A <code>GET</code> request to the\\n            same path would not match this route.</p>\\n        </div>\\n\\n        <div class=\\"step-card\\">\\n            <h3 id=\\"b-the-path-segment-becomes-collection-id\\">B) The path segment becomes <code>collection_id</code></h3>\\n            <p>The route template names one dynamic segment:\\n            <code>{collection_id}</code>. The actual URL supplies\\n            <code>policies</code>, so FastAPI sets:</p>\\n            <div class=\\"result-box\\">collection_id = \\"policies\\"</div>\\n            <p>If the annotation were <code>collection_id: UUID</code> or\\n            <code>collection_id: int</code>, FastAPI would validate and convert\\n            the segment before calling the function.</p>\\n        </div>\\n\\n        <div class=\\"step-card\\">\\n            <h3 id=\\"c-query-string-becomes-top-k\\">C) Query string becomes <code>top_k</code></h3>\\n            <p>From the first line: <code>?top_k=10</code></p>\\n            <ul>\\n                <li>FastAPI finds <code>top_k=\\"10\\"</code> in the query string</li>\\n                <li>Converts <code>\\"10\\"</code> \u2192 <code>10</code> because you typed it as <code>int</code></li>\\n                <li>Checks <code>ge=1</code> and <code>le=50</code></li>\\n                <li>If it wasn\u2019t provided, it would use the default <code>5</code></li>\\n            </ul>\\n            <div class=\\"result-box\\">Result: top_k = 10</div>\\n        </div>\\n\\n        <div class=\\"step-card\\">\\n            <h3 id=\\"d-header-becomes-authorization\\">D) Header becomes <code>authorization</code></h3>\\n            <p>From the headers: <code>Authorization: Bearer abc.def.ghi</code></p>\\n            <p>Because you wrote: <code>authorization: str | None = Header(None)</code></p>\\n            <p>FastAPI reads the Authorization header and sets:</p>\\n            <div class=\\"result-box\\">authorization = \\"Bearer abc.def.ghi\\"</div>\\n            <p><em>If the header was missing, it would be None.</em></p>\\n        </div>\\n\\n        <div class=\\"step-card\\">\\n            <h3 id=\\"e-json-body-becomes-req\\">E) JSON body becomes <code>req</code></h3>\\n            <p>From the body:</p>\\n            <pre>{ \\"question\\": \\"What does my policy say about refunds?\\" }</pre>\\n            <p>Because <code>req</code> is a Pydantic model (<code>QueryReq</code>), FastAPI:</p>\\n            <ol>\\n                <li>parses the JSON into a dict</li>\\n                <li>validates it matches <code>QueryReq</code> (must have <code>question: str</code>)</li>\\n                <li>constructs a Python object:</li>\\n            </ol>\\n            <div class=\\"result-box\\">req = QueryReq(question=\\"What does my policy say about refunds?\\")</div>\\n            <p>So inside your function:</p>\\n            <ul>\\n                <li><code>req</code> is not \u201cthe raw request\u201d</li>\\n                <li><code>req</code> is a validated object built from the JSON body</li>\\n                <li>you access fields like <code>req.question</code></li>\\n            </ul>\\n        </div>\\n\\n        <hr>\\n\\n        <h2 id=\\"4-what-fastapi-effectively-calls-conceptually\\">4) What FastAPI effectively calls (conceptually)</h2>\\n<pre><code class=\\"language-python\\">query(\\n    collection_id=\\"policies\\",\\n    req=QueryReq(question=\\"What does my policy say about refunds?\\"),\\n    top_k=10,\\n    authorization=\\"Bearer abc.def.ghi\\",\\n)</code></pre>\\n\\n        <p>This is a mental model, not literal generated source code. FastAPI\\n        also resolves dependencies, handles async/sync execution, and builds an\\n        HTTP response around the return value.</p>\\n\\n        <div class=\\"tr-note\\">\\n            <strong>Summary:</strong> That\u2019s the whole mapping: query params \u2192 normal args, headers \u2192 <code>Header(...)</code> args, JSON body \u2192 Pydantic model arg (<code>req</code>), and the method+path choose the endpoint.\\n        </div>\\n\\n        <h2 id=\\"5-how-fastapi-decides-where-a-parameter-comes-from\\">5) How FastAPI decides where a parameter comes from</h2>\\n\\n        <table>\\n          <thead><tr><th>Declaration</th><th>Source</th><th>Example</th></tr></thead>\\n          <tbody>\\n            <tr><td>Name appears in the route template</td><td>Path</td><td><code>collection_id: str</code></td></tr>\\n            <tr><td>Simple scalar with no path match</td><td>Query by default</td><td><code>top_k: int = 5</code></td></tr>\\n            <tr><td><code>Header(...)</code></td><td>Header</td><td><code>authorization</code></td></tr>\\n            <tr><td><code>Cookie(...)</code></td><td>Cookie</td><td>Application session cookie</td></tr>\\n            <tr><td><code>Body(...)</code> or Pydantic model</td><td>Request body</td><td><code>req: QueryReq</code></td></tr>\\n            <tr><td><code>Depends(...)</code></td><td>Dependency graph</td><td>Verified identity, database session, service</td></tr>\\n            <tr><td><code>Form(...)</code> / <code>File(...)</code></td><td>Form or multipart body</td><td>Login form or uploaded file</td></tr>\\n          </tbody>\\n        </table>\\n\\n        <p>Use explicit helpers when ambiguity would make the contract harder\\n        to read. In production, authentication normally becomes a security\\n        dependency rather than a raw optional string:</p>\\n\\n<pre><code class=\\"language-python\\">from fastapi import Depends\\n\\ndef query(\\n    collection_id: str,\\n    req: QueryReq,\\n    identity: Identity = Depends(get_verified_identity),\\n    top_k: Annotated[int, Query(ge=1, le=50)] = 5,\\n) -&gt; QueryResponse:\\n    ...</code></pre>\\n\\n        <h2 id=\\"6-invalid-input-stops-before-business-logic\\">6) Invalid input stops before business logic</h2>\\n\\n        <p>If <code>top_k=abc</code>, if <code>top_k=1000</code>, or if the JSON\\n        body omits <code>question</code>, FastAPI does not call\\n        <code>query()</code>. Validation produces a structured\\n        <code>422 Unprocessable Content</code> response that identifies the\\n        source and field path.</p>\\n\\n<pre><code class=\\"language-json\\">{\\n  \\"detail\\": [\\n    {\\n      \\"type\\": \\"less_than_equal\\",\\n      \\"loc\\": [\\"query\\", \\"top_k\\"],\\n      \\"msg\\": \\"Input should be less than or equal to 50\\",\\n      \\"input\\": \\"1000\\"\\n    }\\n  ]\\n}</code></pre>\\n\\n        <p>Malformed JSON is also a client-input error. Authentication failures\\n        should be <code>401</code>; authenticated callers without permission\\n        should receive <code>403</code>; a hidden or absent resource is commonly\\n        <code>404</code>. Do not turn all client errors into <code>500</code>.</p>\\n\\n        <h2 id=\\"7-the-return-value-travels-back-through-a-response-contract\\">7) The return value travels back through a response contract</h2>\\n\\n        <p><code>response_model=QueryResponse</code> validates and serializes\\n        the returned data. It also filters undeclared fields, which helps\\n        prevent internal values from leaking into the API response. FastAPI\\n        uses the request and response models to generate OpenAPI documentation.</p>\\n\\n<pre><code class=\\"language-http\\">HTTP/1.1 200 OK\\nContent-Type: application/json\\n\\n{\\n  \\"collection_id\\": \\"policies\\",\\n  \\"q\\": \\"What does my policy say about refunds?\\",\\n  \\"top_k\\": 10,\\n  \\"auth_header\\": \\"Bearer abc.def.ghi\\"\\n}</code></pre>\\n\\n        <div class=\\"tr-tip\\">\\n          <strong>Next conceptual step</strong>\\n          This chapter treated <code>QueryReq</code> as a black box that\\n          validates a body. The next chapter opens that box, beginning with\\n          ordinary Python classes and dataclasses before deriving Pydantic\\n          models, constraints, aliases, serialization, settings, and API\\n          contracts.\\n        </div>\\n    </div>"}'),i={title:"From an HTTP Message to FastAPI Function Arguments",slug:"/part2-backend-platform-security/03-fastapi-request-mapping",description:"The HTTP chapter separated method, URL, headers, and body. This chapter follows one request through FastAPI and shows exactly how each part becomes a typed Python value. The Pydantic chapter then explains the body mod...",sidebar_label:"3. FastAPI request mapping",pagination_label:"3. FastAPI request mapping",hide_title:!0,hide_table_of_contents:!0},c=void 0,l={},p=[];function h(e){return(0,o.jsx)(r.A,{content:d})}function u(e={}){const{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(h,{...e})}):h()}}}]);